"""Generate the sorted Discord artwork lookup from the bundled public title-ID index."""
import json
from pathlib import Path

root = Path(__file__).resolve().parents[2]
index = json.loads((root / 'misc/discord-artwork-index.json').read_text(encoding='utf-8'))
entries = sorted(index['icons'].items())
lines = [
    '// Generated by tools/discord_release/generate-artwork.py; do not edit by hand.',
    '// Title-ID index: ghost-land/3dsdb, GPL-3.0; see misc/licenses/3dsdb-artwork.txt.',
    '#pragma once', '', '#include <array>', '#include <cstdint>', '#include <string_view>', '',
    'namespace DiscordRPC {', '',
    'struct GameArtworkEntry {', '    std::uint64_t title_id;',
    '    std::string_view category;', '};', '',
    'inline constexpr std::string_view GameArtworkBaseUrl =',
    f'    "https://raw.githubusercontent.com/ghost-land/3dsdb/{index["revision"]}/db/3ds/";', '',
    f'inline constexpr std::array<GameArtworkEntry, {len(entries)}> GameArtworkCatalog{{{{',
]
for title_id, category in entries:
    if len(title_id) != 16 or category not in ('base', 'virtual-console'):
        raise ValueError('Invalid title-ID index entry')
    int(title_id, 16)
    lines.append(f'    {{0x{title_id}ULL, "{category}"}},')
lines += ['}};', '', '} // namespace DiscordRPC', '']
(root / 'src/citra_qt/discord_artwork_catalog.h').write_text('\n'.join(lines), encoding='utf-8')
print(f'Generated {len(entries)} game artwork entries')
